-- Publishes the article "CFA Level I in 2027: Ethics shrinks, Quant nearly doubles" (journal/cfa-level-i-2027-topic-weights).
-- Safe to run once; running it again changes nothing (ON CONFLICT DO NOTHING).
INSERT INTO articles (slug, status, author_id, format, category, difficulty, audience, tags, draft, published,
                      date_published, date_modified)
SELECT 'cfa-level-i-2027-topic-weights', 'published', id, 'Explainer', 'CFA Curriculum', 'Foundation',
       '{CFA Level I}', '{CFA,Level I,Topic weights,2027 curriculum,Quantitative Methods,Ethics}', doc, doc, now(), now()
FROM admin_users, (SELECT $article${"title": "CFA Level I in 2027: Ethics shrinks, Quant nearly doubles", "slug": "cfa-level-i-2027-topic-weights", "subtitle": "November 2026 vs February 2027: all ten topic weights compared, and how to move your study hours.", "excerpt": "From February 2027, Ethics falls to 10–15% of the CFA Level I exam and Quantitative Methods rises to 11–14%. That moves about 9 questions. Here is the full table, what changed inside Quant, and how to re-split 300 study hours.", "format": "Explainer", "category": "CFA Curriculum", "difficulty": "Foundation", "audience": ["CFA Level I"], "tags": ["CFA", "Level I", "Topic weights", "2027 curriculum", "Quantitative Methods", "Ethics"], "featuredImage": {"url": "/journal/cfa-level-i-2027-topic-weights.png", "alt": "CFA Level I 2027: Ethics falls from 15–20% to 10–15%, Quantitative Methods rises from 6–9% to 11–14%", "caption": ""}, "seo": {"title": "CFA Level I Topic Weights: Nov 2026 vs Feb 2027 Compared", "description": "CFA Level I 2027 topic weights: Ethics drops to 10–15%, Quant rises to 11–14%. Full table, renamed topics and how to re-split 300 study hours.", "canonical": "", "ogTitle": "", "ogDescription": "", "ogImage": ""}, "social": {"hook": "CFA Level I just moved about 9 questions from Ethics to Quant.", "body": "From February 2027:\n\n• Ethics: 15–20% → 10–15%\n• Quantitative Methods: 6–9% → 11–14%\n• Derivatives (now Derivatives and Risk Management): 5–8% → 6–9%\n• Alternative Investments: 7–10% → 6–9%\n\nOn a 300-hour plan that is about 15 hours to take out of Ethics and put into Quant. Quant also gets a new module: Introduction to Financial Data Science.\n\nIf you study from 2026 books, Quant is the topic where they fall short.", "question": "Sitting Level I in 2027: which topic are you most worried about?", "hashtags": ["CFA", "CFALevel1", "CFAExam", "Finance", "QuantitativeFinance"], "imageUrl": "/journal/cfa-level-i-2027-topic-weights.png", "carousel": [{"title": "CFA Level I 2027: what moved", "points": ["Ethics 15–20% → 10–15%", "Quant 6–9% → 11–14%", "About 9 questions change hands"]}, {"title": "Smaller moves", "points": ["Derivatives and Risk Management 5–8% → 6–9%", "Alternative Investments 7–10% → 6–9%", "6 topics unchanged"]}, {"title": "Renamed", "points": ["Corporate Issuers → Corporate Finance", "Equity Investments → Equities", "Derivatives → Derivatives and Risk Management", "Portfolio Management → Portfolio Construction"]}, {"title": "New in Quant", "points": ["11 learning modules", "Simulation and regression in finance", "Introduction to Financial Data Science"]}, {"title": "What to do", "points": ["Move about 15 of 300 hours from Ethics to Quant", "Don't use 2026 books for Quant", "Still review Ethics twice"]}], "status": "drafted"}, "cta": {"label": "Book free diagnostic", "href": "/#book", "text": "Sitting Level I in 2027? In a free 30-minute diagnostic we check your Quant against the new modules and re-split your hours for your exam date."}, "disclaimer": "", "sources": [{"id": "cfa", "title": "CFA Program Level I exam: topic weights for 2026 and 2027", "publisher": "CFA Institute", "url": "https://www.cfainstitute.org/programs/cfa/candidate/level-i-study-sessions", "accessedAt": "2026-11-18", "citation": ""}, {"id": "outline", "title": "2027 Level I Topic Outlines", "publisher": "CFA Institute", "url": "https://www.cfainstitute.org/sites/default/files/2027levelitopicoutline_online.pdf", "accessedAt": "2026-11-18", "citation": ""}, {"id": "garp", "title": "FRM Exam Part I: format and topic weights", "publisher": "GARP", "url": "https://www.garp.org/frm", "accessedAt": "2026-11-18", "citation": ""}], "blocks": [{"id": "takeaway", "type": "takeaway", "role": "takeaway", "points": ["From the February 2027 window, Ethics falls from 15–20% to 10–15% of the CFA® Level I exam, and Quantitative Methods rises from 6–9% to 11–14%.", "At the midpoints that is about 9 of the 180 questions moving from Ethics to Quant. Six topics keep their weight and four are renamed.", "On a 300-hour plan, move about 15 hours from Ethics to Quant, and don't study Quant from 2026 books."]}, {"id": "h-context", "type": "heading", "level": 2, "text": "Why it matters"}, {"id": "context", "type": "text", "role": "context", "text": "Which table applies depends on your exam window, not on when you started studying.\n\n- **November 2026 window:** the 2026 curriculum and 2026 weights.\n- **February 2027 onward:** the 2027 curriculum and 2027 weights[^cfa].\n\nCFA Institute publishes both tables on the same page[^cfa], so it is easy to read the wrong one. Some prep sites also still say the 2027 weights are unchanged. The official page says otherwise.\n\nMost second-hand notes and question banks were written for 2026. They give Quant about half the space it now gets on the exam. If you sit in February or May 2027, Quant is where old material falls short."}, {"id": "h-concept", "type": "heading", "level": 2, "text": "Core concept: what moved"}, {"id": "concept", "type": "text", "role": "concept", "text": "The exam is still 180 multiple-choice questions in two sessions of 135 minutes, and every question carries the same marks. Only the share of questions per topic changed[^cfa].\n\nTwo moves matter. Two are small. Six topics stay where they were:"}, {"id": "weights", "type": "table", "role": "concept", "caption": "CFA Level I topic weights, 2026 vs 2027 (ranges from CFA Institute; question change at midpoints of 180)", "source": "CFA Institute, CFA Program Level I exam", "csv": "Topic (2027 name),2026 name,2026 weight,2027 weight,Change in questions\nEthical and Professional Standards,same,15–20%,10–15%,about −9\nQuantitative Methods,same,6–9%,11–14%,about +9\nEconomics,same,6–9%,6–9%,0\nFinancial Statement Analysis,same,11–14%,11–14%,0\nCorporate Finance,Corporate Issuers,6–9%,6–9%,0\nEquities,Equity Investments,11–14%,11–14%,0\nFixed Income,same,11–14%,11–14%,0\nDerivatives and Risk Management,Derivatives,5–8%,6–9%,about +2\nAlternative Investments,same,7–10%,6–9%,about −2\nPortfolio Construction,Portfolio Management,8–12%,8–12%,0"}, {"id": "h-quant", "type": "heading", "level": 3, "text": "What changed inside Quant"}, {"id": "quant", "type": "text", "role": "concept", "text": "Quant now has 11 learning modules, all framed around returns and prices rather than abstract statistics[^outline]:\n\n1. Returns of Financial Assets and Instruments\n2. Types of Financial Returns\n3. Benchmarking Returns\n4. The Time Value of Money in Finance\n5. Statistical Characteristics of Asset Returns\n6. Statistical Distributions for Financial Asset Prices and Returns\n7. Estimation and Hypothesis Testing\n8. The Return and Risk of a Financial Portfolio\n9. Simulation of Financial Asset Prices and Returns\n10. Applications of Simple Linear Regression in Finance\n11. Introduction to Financial Data Science (new)\n\n**Where you meet this at work.** A performance analyst checks a fund against its benchmark every month (module 3). An equity analyst regresses a stock's returns on the index to estimate beta (module 10). A risk team simulates thousands of price paths to estimate a loss level, which is Monte Carlo Value at Risk (module 9, see [three ways to compute VaR](/journal/three-ways-to-compute-var)). Research teams now use Python and language models to read filings and earnings-call transcripts at scale (module 11)."}, {"id": "frm-bridge", "type": "callout", "role": "concept", "tone": "key-insight", "title": "If you also plan FRM", "text": "The new Quant modules on distributions, hypothesis testing, simulation and regression overlap with Quantitative Analysis in FRM® Part I, which is 20% of that exam[^garp]. Learn them properly once for CFA Level I and you have a head start on FRM. CFA asks what the number means for an investment decision; FRM asks what it says about the risk of loss."}, {"id": "h-formula", "type": "heading", "level": 2, "text": "Formula"}, {"id": "formula", "type": "formula", "role": "formula", "tex": "Q_i \\approx \\frac{w_i^{\\text{low}} + w_i^{\\text{high}}}{2} \\times 180", "explanation": "Q is the expected number of questions on topic i. The low and high w are the ends of CFA Institute's weight range. 180 is the number of Level I questions. The midpoint is an estimate: the real count on your exam can sit anywhere in the range."}, {"id": "h-example", "type": "heading", "level": 2, "text": "Worked example: re-splitting 300 hours"}, {"id": "example", "type": "text", "role": "example", "text": "**Step 1: questions.** Ethics at the 2026 midpoint is 17.5% × 180 = 31.5 questions. At the 2027 midpoint it is 12.5% × 180 = 22.5. That is 9 fewer. Quant goes from 7.5% × 180 = 13.5 to 12.5% × 180 = 22.5, which is 9 more.\n\n**Step 2: hours.** Split 300 hours in proportion to each topic's midpoint. The ten midpoints add up to 102.5% in both years, because the ranges overlap, so divide by 102.5 rather than 100:"}, {"id": "hours-formula", "type": "formula", "role": "example", "tex": "H_i = 300 \\times \\frac{m_i}{\\sum_j m_j} \\qquad H_{\\text{Ethics}}^{2027} = 300 \\times \\frac{12.5}{102.5} \\approx 36.6", "explanation": "H is study hours for topic i, m is the topic's midpoint weight, and the sum runs over all ten topics."}, {"id": "hours", "type": "table", "role": "example", "caption": "300 study hours split by midpoint weight, 2026 vs 2027 curriculum", "source": "Finance in Practice calculation from CFA Institute weights", "csv": "Topic,2026 hours,2027 hours,Change\nEthical and Professional Standards,51,37,−14\nQuantitative Methods,22,37,+15\nEconomics,22,22,0\nFinancial Statement Analysis,37,37,0\nCorporate Finance,22,22,0\nEquities,37,37,0\nFixed Income,37,37,0\nDerivatives and Risk Management,19,22,+3\nAlternative Investments,25,22,−3\nPortfolio Construction,29,29,0"}, {"id": "example-read", "type": "text", "role": "example", "text": "Rounded, Ethics and Quant each end up with about 37 hours. They now get the same time as Financial Statement Analysis, Equities and Fixed Income. No single topic leads the exam any more. Treat this as a starting point and add hours where your practice scores are weakest."}, {"id": "h-chart", "type": "heading", "level": 2, "text": "Chart: where the 180 questions move"}, {"id": "chart", "type": "image", "role": "chart", "url": "/journal/cfa-level-i-2027-topic-weights-chart.png", "alt": "Range bars for all ten CFA Level I topics: Ethics drops about 9 questions and Quant gains about 9, Derivatives gains and Alternatives loses about 2, six topics unchanged", "caption": "Gold dashed bars: 2026 range. Cyan bars: 2027 range.", "chart": {"source": "CFA Institute, CFA Program Level I exam", "asOf": "2026-11-18"}}, {"id": "pitfalls", "type": "callout", "role": "pitfalls", "tone": "exam-trap", "title": "Exam traps & common mistakes", "text": "- **Studying Quant from 2026 books.** They cover fewer modules, and the new data science module isn't in them at all.\n- **Reading 10–15% as \"Ethics is optional\".** It is still 18 to 27 questions, about as many as Fixed Income. The Standards are wordy, and they are forgotten fast if you only read them once.\n- **Reading the wrong table.** CFA Institute shows 2026 and 2027 on the same page. Check your exam month first.\n- **Old topic names in mock reports.** A 2026 mock that reports \"Corporate Issuers\" or \"Portfolio Management\" is measuring the 2026 curriculum, not the one you will sit."}, {"id": "h-limits", "type": "heading", "level": 2, "text": "Limitations"}, {"id": "limits", "type": "text", "role": "limitations", "text": "Weights are ranges, not quotas. Midpoints are a planning estimate, and the real count on your form may differ by a few questions. Hours in proportion to weight assume every topic is equally hard for you. In practice, Financial Statement Analysis and Quant usually need more than their share. This post covers Level I only. Check CFA Institute's page again before each exam window, because Level I weights are set for each curriculum year[^cfa]."}, {"id": "vocab", "type": "callout", "role": "limitations", "tone": "note", "title": "Words worth knowing", "text": "- **Reallocate** (ree-AL-uh-kayt): to move a resource from one use to another. *We reallocated 15 hours from Ethics to Quant.*\n- **Recalibrate** (ree-KAL-ih-brayt): to adjust a plan to new conditions. *The 2027 weights mean recalibrating your plan.*\n- **Salient** (SAY-lee-ent): most noticeable or important. *The salient change is in Quantitative Methods.*"}, {"id": "faq", "type": "faq", "items": [{"q": "Which CFA Level I weights apply to my exam?", "a": "The November 2026 window uses the 2026 weights. February 2027 and later use the 2027 weights, with Ethics at 10–15% and Quantitative Methods at 11–14%."}, {"q": "Can I use 2026 study material for the 2027 Level I exam?", "a": "For most topics, yes. For Quantitative Methods, Equities and Ethics, use 2027 material. Quant changed the most and has a new module on financial data science."}, {"q": "Is Ethics still important on CFA Level I?", "a": "Yes. At 10–15% it is still about 18 to 27 questions, as many as the biggest technical topics."}, {"q": "What is the heaviest CFA Level I topic in 2027?", "a": "No single topic leads. Ethics is 10–15%, and Quantitative Methods, Financial Statement Analysis, Equities and Fixed Income are 11–14% each."}]}, {"id": "related", "type": "related", "slugs": ["cfa-level-i-study-plan", "three-ways-to-compute-var"]}]}$article$::jsonb AS doc) AS seed
WHERE role = 'owner' ORDER BY created_at LIMIT 1
ON CONFLICT (slug) DO NOTHING;

SELECT slug, status, date_published FROM articles WHERE slug = 'cfa-level-i-2027-topic-weights';
